fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var sum = 0;
    var i = 1;
    while i <= 40 {
        sum = sum + i;
        i = i + 1;
    }

    var product = 1;
    var j = 1;
    while j <= 8 {
        product = product * j;
        j = j + 1;
    }

    let output = sum.to_text().concat(other: " ").concat(other: product.to_text());
    io.write(text: output)?;
    return Ok(unit);
}

fn sum_to(n: Int) -> Int {
    var total = 0;
    var i = 1;
    while i <= n {
        total = total + i;
        i = i + 1;
    }
    total
}

fn line_for(n: Int) -> String {
    let prefix = n.to_text();
    let sum_text = sum_to(n).to_text();
    prefix.concat(other: ": ").concat(other: sum_text).concat(other: "\n")
}

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    io.write(text: line_for(n: 12))?;
    io.write(text: line_for(n: 30))?;
    io.write(text: line_for(n: 7))?;
    return Ok(unit);
}
